package com.securedeploy.editing;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.securedeploy.auth.service.ReviewAccessService;
import com.securedeploy.persistence.entity.ReviewEntity;
import com.securedeploy.sca.client.VulnerabilityDataSource;
import com.securedeploy.sca.model.*;
import com.securedeploy.sca.service.DependencyUpdatePlanService;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.env.MockEnvironment;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class NpmTreePlanTest {
 final ObjectMapper json=new ObjectMapper();final EditingWorkspaceService ws=mock(EditingWorkspaceService.class);final DependencyUpdatePlanService plans=mock(DependencyUpdatePlanService.class);final ReviewAccessService access=mock(ReviewAccessService.class);final NpmRegistry registry=mock(NpmRegistry.class);final NpmTreeExecutor npm=mock(NpmTreeExecutor.class);final VulnerabilityDataSource osv=mock(VulnerabilityDataSource.class);final MockEnvironment env=new MockEnvironment();WorkspaceNpmTreeService service;
 byte[] manifest,lock;List<SourceArchive.Entry> entries;String manifestText="{\"name\":\"owned-independent-fixture\",\"dependencies\":{\"build-kit\":\"1.0.0\",\"normal-core\":\"9.0.0\"},\"scripts\":{\"install\":\"must-not-run\"}}";
 byte[] bytes(String s){return s.getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 ObjectNode pkg(String name,String version)throws Exception {var p=json.createObjectNode().put("version",version).put("resolved","https://registry.npmjs.org/"+name+"/-/"+name+"-"+version+".tgz").put("integrity","sha512-"+name+version);return p;}
 DependencyVulnerability finding(String name,String version,String id){return new DependencyVulnerability(ScaEcosystem.NPM,name,version,id,List.of(),"captured synthetic advisory",null,null,List.of(),List.of("1.0.1"),null,null,List.of(),List.of("package-lock.json"));}
 @BeforeEach void setup()throws Exception{
  when(npm.available()).thenReturn(true); // Explicit mock adapter; no OS isolation claim.
  manifest=bytes(manifestText);var l=json.createObjectNode().put("lockfileVersion",3);var ps=l.putObject("packages");ps.set("",json.readTree(manifest));ps.set("node_modules/build-kit",pkg("build-kit","1.0.0").set("dependencies",json.createObjectNode().put("transport-core","1.0.0")));ps.set("node_modules/transport-core",pkg("transport-core","1.0.0"));ps.set("node_modules/normal-core",pkg("normal-core","9.0.0"));lock=json.writeValueAsBytes(l);
  entries=List.of(new SourceArchive.Entry("package.json",manifest,false,0100644),new SourceArchive.Entry("package-lock.json",lock,false,0100644));
  when(ws.captureScan("w",1)).thenAnswer(i->new EditingWorkspaceService.ScanInput(1,"CONTROL",new WorkspaceScanSnapshot(1,"w",1,10,1,"sha","VERIFIED_ZIP_MANIFEST","input",java.time.Instant.now(),"ts-server-v56",true,List.of(),""),entries.stream().map(e->new SourceArchive.Entry(e.path(),e.bytes().clone(),false,e.mode())).toList()));
  var plan=mock(DependencyUpdatePlanService.Plan.class);when(plan.ecosystem()).thenReturn("NPM");when(plan.packageName()).thenReturn("transport-core");when(plan.lockedVersion()).thenReturn("1.0.0");var snap=mock(DependencyUpdatePlanService.Snapshot.class);when(snap.plans()).thenReturn(List.of(plan));when(plans.get(10)).thenReturn(snap);var review=mock(ReviewEntity.class);var sca=mock(ScaResult.class);when(sca.dependencyVulnerabilities()).thenReturn(List.of(finding("transport-core","1.0.0","GHSA-old")));when(review.getScaResult()).thenReturn(sca);when(access.findAccessibleReviewWithVulnerabilities(eq(10L),anyString())).thenReturn(review);
  var release=json.createObjectNode().put("name","build-kit").put("version","1.0.1");release.putObject("dependencies").put("transport-core","1.0.1");release.putObject("dist").put("integrity","sha512-build-kit1.0.1").put("tarball","https://registry.npmjs.org/build-kit/-/build-kit-1.0.1.tgz");when(registry.releases("build-kit","1.0.0")).thenReturn(List.of(release));
  when(npm.generate(any(),any(),anyString(),anyString(),anyString())).thenAnswer(i->{var m=(ObjectNode)json.readTree(manifest);((ObjectNode)m.path("dependencies")).put("build-kit","1.0.1");var n=(ObjectNode)json.readTree(lock);((ObjectNode)n.path("packages")).set("",m);((ObjectNode)n.path("packages")).set("node_modules/build-kit",pkg("build-kit","1.0.1").set("dependencies",json.createObjectNode().put("transport-core","1.0.1")));((ObjectNode)n.path("packages")).set("node_modules/transport-core",pkg("transport-core","1.0.1"));return new NpmTreeExecutor.Output(json.writeValueAsBytes(m),json.writeValueAsBytes(n),"11.12.1","v26.0.0");});
  when(osv.lookup(anyList())).thenAnswer(i->{List<DependencyComponent> all=i.getArgument(0);return new VulnerabilityDataSource.LookupResult(List.of(finding("transport-core","1.0.0","GHSA-old")),all.stream().map(DependencyComponent::identity).collect(java.util.stream.Collectors.toSet()),false,List.of());});when(ws.generatedDifferences(anyString(),anyLong(),anyString(),anyMap())).thenReturn(List.of());service=new WorkspaceNpmTreeService(ws,plans,access,registry,npm,osv,json,env,true);
 }
 WorkspaceNpmTreeService.View prepare(){return service.prepare("w",new WorkspaceNpmTreeService.Prepare(1,0));}
 WorkspaceNpmTreeService.View generate(WorkspaceNpmTreeService.View p){return service.generate("w",p.id(),new WorkspaceNpmTreeService.Consent("input",true));}
 @Test void unavailableIsolationStopsBeforeRegistryOrCaptureEvenWithEnabledFlag(){
  when(npm.available()).thenReturn(false);assertFalse(service.enabled());
  var error=assertThrows(com.securedeploy.global.error.SecureDeployException.class,this::prepare);
  assertEquals(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,error.getStatus());
  assertTrue(error.getMessage().contains("안전한 실행 환경"));
  verify(ws,never()).captureScan(anyString(),anyLong());verifyNoInteractions(registry,osv);
 }
 @Test void parentUpdateUsesOneUnionFeedAndPreservesNormalPaths()throws Exception{var p=prepare();assertEquals("build-kit",p.rootPackage());assertEquals(1,p.affectedPaths().size());assertEquals("PROPOSED",generate(p).state());verify(osv,times(1)).lookup(anyList());verifyNoInteractionsAfterPrepareNotPossible();}
 void verifyNoInteractionsAfterPrepareNotPossible(){verify(ws,never()).applyGenerated(anyString(),anyLong(),anyString(),anyMap(),anyString(),anyString());}
 @Test void noSafeParentReturnsConcreteManualGuideWithoutForcedOverride()throws Exception{when(registry.releases(anyString(),anyString())).thenReturn(List.of());var p=generate(prepare());assertEquals("MANUAL_REVIEW",p.state());assertFalse(p.remainingPaths().isEmpty());assertTrue(p.message().contains("override"));verify(npm,never()).generate(any(),any(),anyString(),anyString(),anyString());}
 @Test void knownOldChildIsSkippedWithoutNpm()throws Exception{var r=json.createObjectNode().put("name","build-kit").put("version","1.0.1");r.putObject("dependencies").put("transport-core","1.0.0");when(registry.releases(anyString(),anyString())).thenReturn(List.of(r));assertEquals("MANUAL_REVIEW",generate(prepare()).state());verify(npm,never()).generate(any(),any(),anyString(),anyString(),anyString());}
 @Test void newAdvisoryAndPartialLookupNeverProduceApplicablePlan()throws Exception{for(boolean partial:List.of(false,true)){setup();when(osv.lookup(anyList())).thenAnswer(i->{List<DependencyComponent> all=i.getArgument(0);return new VulnerabilityDataSource.LookupResult(List.of(finding("transport-core","1.0.0","GHSA-old"),finding("build-kit","1.0.1","GHSA-new")),all.stream().map(DependencyComponent::identity).collect(java.util.stream.Collectors.toSet()),partial,List.of());});var result=generate(prepare());assertEquals(partial?"PARTIAL":"MANUAL_REVIEW",result.state());assertEquals(partial?"OSV_PARTIAL_UNKNOWN":"NEW_ADVISORY_INTRODUCED",result.attempts().get(0).outcome());}}
 @Test void generationRequiresMatchingConsentAndCannotBeRepeated(){var p=prepare();assertThrows(RuntimeException.class,()->service.generate("w",p.id(),new WorkspaceNpmTreeService.Consent("different",true)));assertThrows(RuntimeException.class,()->service.generate("w",p.id(),new WorkspaceNpmTreeService.Consent("input",false)));generate(p);assertThrows(RuntimeException.class,()->generate(p));}
 @Test void revisionOwnershipAndReleaseModesFailClosed(){var p=prepare();when(ws.get("foreign")).thenThrow(new IllegalStateException("DENIED"));assertThrows(RuntimeException.class,()->service.get("foreign",p.id()));when(ws.captureScan("w",1)).thenThrow(new com.securedeploy.global.error.SecureDeployException(org.springframework.http.HttpStatus.CONFLICT,"STALE"));assertThrows(RuntimeException.class,()->generate(p));env.setActiveProfiles("release-compatible");assertFalse(service.enabled());env.setActiveProfiles("release-recovery");assertFalse(service.enabled());}
 @Test void unrelatedNormalPathChangeIsRejected()throws Exception{var before=NpmTreePlanner.read(json,manifest,lock);var target=NpmTreePlanner.target(before,"transport-core","1.0.0");var output=npm.generate(manifest,lock,"dependencies","build-kit","1.0.1");var modified=(ObjectNode)json.readTree(output.lockfile());((ObjectNode)modified.path("packages").path("node_modules/normal-core")).put("version","9.0.1");assertThrows(Exception.class,()->NpmTreePlanner.validateGraph(before,NpmTreePlanner.read(json,output.manifest(),json.writeValueAsBytes(modified)),target,"1.0.1"));}
 @Test void multipleRootsAndOptionalRootStopAutomaticPlan()throws Exception{var l=(ObjectNode)json.readTree(lock);((ObjectNode)l.path("packages")).set("node_modules/second-kit",pkg("second-kit","1.0.0").set("dependencies",json.createObjectNode().put("transport-core","1.0.0")));var m=(ObjectNode)json.readTree(manifest);((ObjectNode)m.path("dependencies")).put("second-kit","1.0.0");((ObjectNode)l.path("packages")).set("",m);var multi=NpmTreePlanner.read(json,json.writeValueAsBytes(m),json.writeValueAsBytes(l));assertThrows(Exception.class,()->NpmTreePlanner.target(multi,"transport-core","1.0.0"));m=(ObjectNode)json.readTree(manifest);m.set("optionalDependencies",m.remove("dependencies"));l=(ObjectNode)json.readTree(lock);((ObjectNode)l.path("packages")).set("",m);var optional=NpmTreePlanner.read(json,json.writeValueAsBytes(m),json.writeValueAsBytes(l));assertThrows(Exception.class,()->NpmTreePlanner.target(optional,"transport-core","1.0.0"));}
 @Test void monorepoManagerLinkAndHashEvidenceAreNeverAssumed(){for(String field:List.of("workspaces","overrides","packageManager","resolutions"))assertThrows(Exception.class,()->NpmTreePlanner.read(json,bytes(manifestText.replace("\"scripts\":","\""+field+"\":{},\"scripts\":")),lock));assertFalse(NpmTreePlanner.upgrade("1.0.0","2.0.0"));assertFalse(NpmTreePlanner.upgrade("0.1.0","0.2.0"));assertFalse(NpmTreePlanner.upgrade("1.0.0","1.0.1-beta"));}

 @Test void directDependencyIsItsOwnRootWithoutInventingAParent()throws Exception{var m=(ObjectNode)json.readTree(manifest);((ObjectNode)m.path("dependencies")).remove("build-kit");((ObjectNode)m.path("dependencies")).put("transport-core","1.0.0");var l=(ObjectNode)json.readTree(lock);((ObjectNode)l.path("packages")).remove("node_modules/build-kit");((ObjectNode)l.path("packages")).set("",m);var target=NpmTreePlanner.target(NpmTreePlanner.read(json,json.writeValueAsBytes(m),json.writeValueAsBytes(l)),"transport-core","1.0.0");assertEquals("transport-core",target.root());assertEquals(1,target.chains().get(0).size());}
 @Test void multipleInstalledVersionsKeepTheUnaffectedVersionSeparate()throws Exception{var m=(ObjectNode)json.readTree(manifest);((ObjectNode)m.path("dependencies")).put("other-kit","1.0.0");var l=(ObjectNode)json.readTree(lock);var ps=(ObjectNode)l.path("packages");ps.set("",m);ps.set("node_modules/other-kit",pkg("other-kit","1.0.0").set("dependencies",json.createObjectNode().put("transport-core","2.0.0")));ps.set("node_modules/other-kit/node_modules/transport-core",pkg("transport-core","2.0.0"));var input=NpmTreePlanner.read(json,json.writeValueAsBytes(m),json.writeValueAsBytes(l));assertEquals(2,input.components().stream().filter(c->c.packageName().equals("transport-core")).count());assertEquals(List.of("node_modules/transport-core"),NpmTreePlanner.target(input,"transport-core","1.0.0").paths());}
 @Test void optionalChildIsNotConfusedWithRuntimeExposure()throws Exception{var l=(ObjectNode)json.readTree(lock);var root=(ObjectNode)l.path("packages").path("node_modules/build-kit");root.set("optionalDependencies",root.remove("dependencies"));var input=NpmTreePlanner.read(json,manifest,json.writeValueAsBytes(l));var c=input.components().stream().filter(v->v.packageName().equals("transport-core")).findFirst().orElseThrow();assertTrue(c.context().paths().get(0).optional());assertEquals("NOT_ANALYZED",c.context().runtimeReachability());assertEquals("build-kit",NpmTreePlanner.target(input,"transport-core","1.0.0").root());}
 @Test void npmPeerConflictCannotReachDiffOrApply()throws Exception{when(npm.generate(any(),any(),anyString(),anyString(),anyString())).thenThrow(new IllegalArgumentException("NPM_PEER_ENGINE_OR_RESOLUTION_FAILURE"));assertEquals("MANUAL_REVIEW",generate(prepare()).state());verifyNoInteractions(osv);verify(ws,never()).generatedDifferences(anyString(),anyLong(),anyString(),anyMap());}
 @Test void changedOriginalEvidenceStopsBeforeRegistryOrExecution()throws Exception{when(ws.captureScan("w",1)).thenReturn(new EditingWorkspaceService.ScanInput(1,"CONTROL",new WorkspaceScanSnapshot(1,"w",1,10,1,"sha","UNVERIFIED","input",java.time.Instant.now(),"ts-server-v56",false,List.of(),""),entries));assertThrows(RuntimeException.class,this::prepare);verifyNoInteractions(registry,osv);verify(npm,never()).generate(any(),any(),anyString(),anyString(),anyString());}

 @Test void declaredRangeAndLockedRootCannotDisagree()throws Exception{assertTrue(NpmTreePlanner.satisfies("^1.0.0","1.2.0"));assertFalse(NpmTreePlanner.satisfies("~1.0.0","1.1.0"));assertFalse(NpmTreePlanner.satisfies("^0.0.1","0.0.2"));var m=(ObjectNode)json.readTree(manifest);((ObjectNode)m.path("dependencies")).put("build-kit","^2.0.0");var l=(ObjectNode)json.readTree(lock);((ObjectNode)l.path("packages")).set("",m);var inconsistent=NpmTreePlanner.read(json,json.writeValueAsBytes(m),json.writeValueAsBytes(l));assertThrows(Exception.class,()->NpmTreePlanner.target(inconsistent,"transport-core","1.0.0"));}
}
